import React, { useState, useEffect, useRef } from 'react';
import QRCode from 'qrcode.js';
import { Html5QrcodeScanner } from 'html5-qrcode';

const App: React.FC = () => {
  const [mode, setMode] = useState<'generator' | 'scanner'>('generator');
  const [text, setText] = useState('');
  const [scanResult, setScanResult] = useState<string | null>(null);
  const qrCodeRef = useRef<HTMLDivElement>(null);
  const scannerRef = useRef<Html5QrcodeScanner | null>(null);

  useEffect(() => {
    if (mode === 'generator' && qrCodeRef.current) {
      qrCodeRef.current.innerHTML = '';
      new QRCode(qrCodeRef.current, {
        text: text || 'https://gemini.google.com',
        width: 256,
        height: 256,
        colorDark: '#000000',
        colorLight: '#ffffff',
        correctLevel: 3,
      });
    }
  }, [mode, text]);

  useEffect(() => {
    if (mode === 'scanner') {
      const scanner = new Html5QrcodeScanner(
        'qr-reader',
        { fps: 10, qrbox: 250 },
        false
      );
      scannerRef.current = scanner;

      const onScanSuccess = (decodedText: string) => {
        setScanResult(decodedText);
        scanner.clear();
      };

      scanner.render(onScanSuccess, undefined);

      return () => {
        scanner.clear();
      };
    }
  }, [mode]);

  const handleDownload = () => {
    const canvas = qrCodeRef.current?.querySelector('canvas');
    if (canvas) {
      const link = document.createElement('a');
      link.download = 'qrcode.png';
      link.href = canvas.toDataURL('image/png');
      link.click();
    }
  };

  const handleCopy = () => {
    if (scanResult) {
      navigator.clipboard.writeText(scanResult);
    }
  };

  const handleRestart = () => {
    setScanResult(null);
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center font-sans">
      <div className="w-full max-w-md p-8 space-y-8 bg-white rounded-3xl shadow-2xl">
        <div className="flex justify-center">
          <div className="relative flex p-1 bg-gray-200 rounded-full">
            <button
              onClick={() => setMode('generator')}
              className={`relative z-10 px-6 py-2 text-sm font-medium rounded-full transition-colors duration-300 ${
                mode === 'generator' ? 'text-white' : 'text-gray-600'
              }`}
            >
              Generator
            </button>
            <button
              onClick={() => setMode('scanner')}
              className={`relative z-10 px-6 py-2 text-sm font-medium rounded-full transition-colors duration-300 ${
                mode === 'scanner' ? 'text-white' : 'text-gray-600'
              }`}
            >
              Scanner
            </button>
            <div
              className={`absolute top-1 bottom-1 left-1 w-1/2 bg-indigo-600 rounded-full transform transition-transform duration-300 ${
                mode === 'scanner' ? 'translate-x-full' : ''
              }`}
            ></div>
          </div>
        </div>

        {mode === 'generator' && (
          <div className="space-y-6 text-center">
            <div
              ref={qrCodeRef}
              className="flex justify-center items-center p-4 bg-white rounded-3xl shadow-inner"
            ></div>
            <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder="Enter text or URL"
              className="w-full p-4 text-gray-700 bg-gray-100 rounded-3xl shadow-inner focus:outline-none focus:ring-2 focus:ring-indigo-500"
              rows={4}
            ></textarea>
            <button
              onClick={handleDownload}
              className="w-full px-6 py-3 text-white bg-indigo-600 rounded-full shadow-lg hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
            >
              Download QR
            </button>
          </div>
        )}

        {mode === 'scanner' && (
          <div className="space-y-6">
            {scanResult ? (
              <div className="p-6 space-y-4 bg-white rounded-3xl shadow-xl">
                <h3 className="text-lg font-semibold text-center text-gray-800">Scan Result</h3>
                <p className="text-center text-gray-600 break-all">{scanResult}</p>
                <div className="flex space-x-4">
                  <button
                    onClick={handleCopy}
                    className="w-full px-4 py-2 text-white bg-indigo-600 rounded-full shadow-lg hover:bg-indigo-700 focus:outline-none"
                  >
                    Copy Result
                  </button>
                  <button
                    onClick={handleRestart}
                    className="w-full px-4 py-2 text-indigo-600 bg-gray-100 rounded-full shadow-lg hover:bg-gray-200 focus:outline-none"
                  >
                    Restart Scan
                  </button>
                </div>
              </div>
            ) : (
              <div id="qr-reader" className="w-full"></div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default App;
